#ifndef MOTOR_H
#define MOTOR_H
// Stepper motor drivers.
//  - FastStepper: TMC2209 in STEP/DIR mode, step pulses generated by hardware
//    (FastAccelStepper), optional UART link for current/microstep config.
//  - SimStepper: virtual motor for testing UI/web without hardware. Pair it
//    with SimMagneticEncoder.
#include <Arduino.h>

class StepperDriver {
public:
    virtual ~StepperDriver() {}
    virtual bool begin() = 0;
    virtual void setSpeedAccel(uint32_t speedHz, uint32_t accel) = 0;
    virtual bool moveTo(int32_t position) = 0;   // absolute, in steps; retargets if running
    virtual void stop() = 0;                     // decelerate to a stop
    virtual void forceStop() = 0;                // stop immediately
    virtual bool isRunning() = 0;
    virtual int32_t position() = 0;
    virtual void setReversed(bool reversed) = 0; // only while stopped
    virtual void setHold(bool hold) = 0;         // keep coils energized when idle
    virtual void tick() {}                       // called every motion loop iteration

    // TMC2209 UART (no-ops in standalone mode)
    virtual bool uartConnected() { return false; }
    virtual void configureDriver(uint16_t runMa, uint8_t holdPct, uint16_t microsteps, bool stealth) {}
    virtual String report() { return "TMC2209 standalone (UART not connected)"; }
};

class FastAccelStepper;
class TMC2209Stepper;

class FastStepper : public StepperDriver {
public:
    FastStepper(uint8_t stepPin, uint8_t dirPin, uint8_t enPin) : _step(stepPin), _dir(dirPin), _en(enPin) {}
    bool begin() override;
    void setSpeedAccel(uint32_t speedHz, uint32_t accel) override;
    bool moveTo(int32_t position) override;
    void stop() override;
    void forceStop() override;
    bool isRunning() override;
    int32_t position() override;
    void setReversed(bool reversed) override;
    void setHold(bool hold) override;

    // Try to talk to the driver over UART (call after begin()).
    bool beginUart(HardwareSerial& serial, int rxPin, int txPin, float rSense, uint8_t address);
    bool uartConnected() override { return _uartOk; }
    void configureDriver(uint16_t runMa, uint8_t holdPct, uint16_t microsteps, bool stealth) override;
    String report() override;

private:
    uint8_t _step, _dir, _en;
    FastAccelStepper* _s = nullptr;
    TMC2209Stepper* _tmc = nullptr;
    bool _uartOk = false;
    bool _reversed = false;
};

class SimStepper : public StepperDriver {
public:
    bool begin() override { _lastUs = micros(); return true; }
    void setSpeedAccel(uint32_t speedHz, uint32_t accel) override { _vmax = speedHz; _acc = accel; }
    bool moveTo(int32_t position) override;
    void stop() override;
    void forceStop() override;
    bool isRunning() override { return _running; }
    int32_t position() override { return (int32_t)lroundf(_pos); }
    void setReversed(bool reversed) override { _reversed = reversed; }
    void setHold(bool) override {}
    void tick() override;
    String report() override { return "Simulated motor"; }

    // Mechanical model: the blind (and encoder) follows the motor between
    // these limits; beyond them the motor slips, like hitting an end stop.
    float stepsPerTick = 1600.0f / 4096.0f;
    float mechMinTicks = -4000, mechMaxTicks = 52000;
    float mechTicks = 0;   // encoder-side position (ticks)

private:
    float _pos = 0, _v = 0, _target = 0;
    float _vmax = 1000, _acc = 1000;
    bool _running = false, _reversed = false;
    uint32_t _lastUs = 0;
};

#endif
